  // neighbours the bump derivative would draw a false horizontal seam.
  d = unravelClosest(d, unravelSegment(q+vec2(0.0,1.0),vec2(0.34,0.52),vec2(0.31,0.23),0.0));
  d = unravelClosest(d, unravelSegment(q-vec2(0.0,1.0),vec2(0.11,-0.19),vec2(0.015,-0.34),0.759));
